sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-14: vehicle data validation (VIN, year, odometer, unique active plate)
    var errors = [];

    var vin = (current.getValue('vin') || '').toUpperCase();
    if (!/^[A-Z0-9]{6}$/.test(vin)) {
        errors.push('VIN (last 6) must be exactly 6 letters or digits.');
    } else {
        current.setValue('vin', vin);
    }

    if (!current.year.nil()) {
        var year = parseInt(current.getValue('year'), 10);
        var maxYear = new GlideDateTime().getYearLocalTime() + 1;
        if (year < 1990 || year > maxYear) {
            errors.push('Year must be between 1990 and ' + maxYear + '.');
        }
    }

    var odo = parseInt(current.getValue('current_odometer') || '0', 10);
    var lastOdo = parseInt(current.getValue('last_maintenance_odometer') || '0', 10);
    if (odo < 0) {
        errors.push('Current Odometer cannot be negative.');
    }
    if (lastOdo > odo) {
        errors.push('Last Maintenance Odometer cannot be more than Current Odometer.');
    }

    var vid = (current.getValue('vehicle_id') || '').trim();
    if (vid) {
        var dup = new GlideRecord('x_1850693_enterp_0_vehicle');
        dup.addQuery('vehicle_id', vid);
        dup.addQuery('sys_id', '!=', current.getUniqueValue());
        dup.setLimit(1);
        dup.query();
        if (dup.hasNext()) {
            errors.push('Vehicle ID ' + vid + ' already exists.');
        }
    }

    var plate = (current.getValue('license_plate') || '').trim();
    if (plate && current.getValue('status') != 'RETIRED') {
        var gr = new GlideRecord('x_1850693_enterp_0_vehicle');
        gr.addQuery('license_plate', plate);
        gr.addQuery('status', '!=', 'RETIRED');
        gr.addQuery('sys_id', '!=', current.getUniqueValue());
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            errors.push('License plate ' + plate + ' is already used by active vehicle ' + gr.getValue('vehicle_id') + '.');
        }
    }

    if (errors.length) {
        for (var i = 0; i < errors.length; i++) {
            gs.addErrorMessage(errors[i]);
        }
        current.setAbortAction(true);
    }
})(current, previous);
